/* js/documents.js
 * Rescue Renewals: sticker, certificate and brown card PDFs.
 *
 * The three documents are the real Enterprise Insurance layouts. Each one is stored below as a
 * blank template (the original PDF with every per-policy value and QR code removed). For each
 * policy the live values are written onto the template with pdf-lib, and a QR code that opens
 * the verification page is drawn as vector squares.
 *
 * Public API (unchanged): generateDocument(type, docContext), generateAll(docContext), downloadDocument(doc)
 * File names: <doc>_<registration>_<YYYYMMDD of inception>.pdf, for example
 *   STICKER_GT-9482-24_20261031.pdf, cert_GT-9482-24_20261031.pdf, brown_card_GT-9482-24_20261031.pdf
 *
 * Needs pdf-lib (1.17.1) and qrcode-generator (already loaded by index.html). pdf-lib is loaded on
 * demand: first from js/vendor/pdf-lib.min.js (drop the file there for offline use), then from a CDN.
 */

const SHOW_DEMO_NOTE = true; // small "demo document" line on each PDF; set to false to hide it
const DEMO_NOTE = 'Demo document generated by Rescue Renewals. Not a real policy.';

const PDF_LIB_SOURCES = [
  new URL('./vendor/pdf-lib.min.js', import.meta.url).href,
  'https://cdn.jsdelivr.net/npm/pdf-lib@1.17.1/dist/pdf-lib.min.js',
  'https://cdnjs.cloudflare.com/ajax/libs/pdf-lib/1.17.1/pdf-lib.min.js'
];

const PREFIX = { sticker: 'STICKER', certificate: 'cert', brown_card: 'brown_card' };

/* ---------- blank templates (base64 PDF) ---------- */
const TEMPLATES = {
  sticker: '',
  certificate: '',
  brown_card: ''
};

/* ---------- loading pdf-lib ---------- */
let pdfLibPromise = null;

function loadScript(src) {
  return new Promise((resolve, reject) => {
    const s = document.createElement('script');
    s.src = src;
    s.async = true;
    s.onload = () => (window.PDFLib ? resolve() : reject(new Error('pdf-lib did not initialise from ' + src)));
    s.onerror = () => { s.remove(); reject(new Error('Could not load ' + src)); };
    document.head.appendChild(s);
  });
}

function loadPdfLib() {
  if (window.PDFLib) return Promise.resolve(window.PDFLib);
  if (!pdfLibPromise) {
    pdfLibPromise = (async () => {
      for (const src of PDF_LIB_SOURCES) {
        try { await loadScript(src); return window.PDFLib; } catch (e) { /* try the next source */ }
      }
      pdfLibPromise = null;
      throw new Error('Could not load the PDF library (pdf-lib). Check the internet connection, or add js/vendor/pdf-lib.min.js.');
    })();
  }
  return pdfLibPromise;
}

function b64ToBytes(b64) {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

/* ---------- text and date helpers ---------- */
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
const CHAR_MAP = { 'ɛ': 'e', 'Ɛ': 'E', 'ɔ': 'o', 'Ɔ': 'O', 'ŋ': 'n', 'Ŋ': 'N', '’': "'", '‘': "'", '“': '"', '”': '"', '–': '-', '—': '-' };

// Standard PDF fonts only handle Latin-1, so swap or drop anything else.
function safe(t) {
  return String(t == null ? '' : t)
    .replace(/[ɛƐɔƆŋŊ’‘“”–—]/g, (c) => CHAR_MAP[c])
    .replace(/[^\x20-\x7E\u00A0-\u00FF]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function dateParts(iso) {
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(iso));
  if (!m) throw new Error('Invalid date: ' + iso);
  return { y: +m[1], m: +m[2], d: +m[3] };
}

function ordinal(n) {
  const s = ['th', 'st', 'nd', 'rd'];
  const v = n % 100;
  return n + (s[(v - 20) % 10] || s[v] || s[0]);
}

const dateSticker = (iso) => { const p = dateParts(iso); return `${MONTHS[p.m - 1]} ${ordinal(p.d)}, ${p.y}`; };            // October 31st, 2026
const dateCert = (iso) => { const p = dateParts(iso); return `${ordinal(p.d)} ${MONTHS[p.m - 1]} ${p.y}`.toUpperCase(); };   // 31ST OCTOBER 2026
const dateBrown = (iso) => { const p = dateParts(iso); return `${String(p.d).padStart(2, '0')}-${MONTHS[p.m - 1].slice(0, 3)}-${p.y}`; }; // 31-Oct-2026

// Deterministic digits from a seed string, so the same policy always gets the same numbers.
function digitsFrom(seed, n) {
  let h = 2166136261;
  let out = '';
  for (let i = 0; out.length < n; i++) {
    const s = seed + ':' + i;
    for (let k = 0; k < s.length; k++) { h ^= s.charCodeAt(k); h = Math.imul(h, 16777619) >>> 0; }
    out += String(h % 10);
  }
  return out;
}

const usageSticker = (u) => (/^private/i.test(u || '') ? 'Private Individual' : safe(u));
const usageBrown = (u) => (/^private/i.test(u || '') ? 'Private' : safe(u));
const coverSticker = (c) => (/third/i.test(c || '') ? 'Third Party Only' : safe(c));
const coverCert = (c) => (/third/i.test(c || '') ? 'Third Party' : safe(c));

function makeAndModel(v) {
  const make = safe(v.make);
  const model = safe(v.model);
  return model.toLowerCase().startsWith(make.toLowerCase()) ? model : (make + ' ' + model).trim();
}

function yearOf(d) { return dateParts(d.startDate).y; }
function sixDigits(src, fallbackSeed) {
  const m = /(\d{6})\D*$/.exec(String(src || ''));
  return m ? m[1] : digitsFrom(fallbackSeed, 6);
}

// Identifiers shown on the documents, derived from the data the app already holds.
function stickerNumber(d) { return 'STEIC' + digitsFrom(d.policyNumber + '|' + d.vehicle.plate, 15); }
function certificateNumber(d) { return 'DMPP' + String(yearOf(d)).slice(2) + '00' + safe(d.vehicle.plate).replace(/\s+/g, ''); }
function brownCardNumber(d) { return 'EBC/GH/EIC/' + yearOf(d) + '/' + sixDigits(d.brownCardNumber, d.policyNumber); }

/* ---------- drawing helpers ---------- */
const BLACK = [0, 0, 0];

function put(c, text, x, y, o = {}) {
  const t = safe(text);
  if (!t) return;
  const font = o.font;
  let size = o.size;
  if (o.maxW) while (size > 5 && font.widthOfTextAtSize(t, size) > o.maxW) size -= 0.25;
  const w = font.widthOfTextAtSize(t, size);
  const px = o.align === 'right' ? x - w : o.align === 'center' ? x - w / 2 : x;
  const col = o.color || BLACK;
  c.page.drawText(t, { x: px, y, size, font, color: c.L.rgb(col[0], col[1], col[2]), rotate: o.rotate });
}

function qrModules(text) {
  if (typeof window.qrcode !== 'function') throw new Error('The QR code library is not loaded.');
  let qr = null;
  for (const level of ['L', 'M']) {
    try { qr = window.qrcode(0, level); qr.addData(text); qr.make(); break; } catch (e) { qr = null; }
  }
  if (!qr) throw new Error('Could not build the QR code.');
  return { n: qr.getModuleCount(), isDark: (r, k) => qr.isDark(r, k) };
}

// Draws the QR code as filled squares (sharp at any zoom). x, y is the bottom-left corner of the box.
function drawQr(c, text, x, y, size, quiet) {
  const q = qrModules(text);
  const cell = size / (q.n + 2 * quiet);
  const col = c.L.rgb(0, 0, 0);
  for (let r = 0; r < q.n; r++) {
    let k = 0;
    while (k < q.n) {
      if (!q.isDark(r, k)) { k++; continue; }
      let run = 0;
      while (k + run < q.n && q.isDark(r, k + run)) run++;
      c.page.drawRectangle({
        x: x + (k + quiet) * cell,
        y: y + size - (r + quiet + 1) * cell,
        width: run * cell + 0.03,
        height: cell + 0.03,
        color: col,
        borderWidth: 0
      });
      k += run;
    }
  }
}

function demoNote(c, x, y, align) {
  if (!SHOW_DEMO_NOTE) return;
  put(c, DEMO_NOTE, x, y, { font: c.F.helv, size: 6, color: [0.45, 0.45, 0.45], align });
}

/* ---------- the three documents ---------- */
// Coordinates are PDF points measured from the bottom-left corner, taken from the original files.

function drawSticker(c) {
  const d = c.d, v = d.vehicle, B = c.F.helvB;
  const x = 101;
  put(c, v.plate, x, 752.65, { font: B, size: 9, maxW: 90 });
  put(c, v.make, x, 737.65, { font: B, size: 9, maxW: 90 });
  put(c, makeAndModel(v), x, 722.65, { font: B, size: 9, maxW: 90 });
  put(c, usageSticker(v.use), x, 700.65, { font: B, size: 9, maxW: 90 });
  put(c, coverSticker(d.coverType), x, 671.65, { font: B, size: 9, maxW: 90 });
  put(c, v.colour, x, 649.65, { font: B, size: 9, maxW: 90 });
  put(c, dateSticker(d.startDate), x, 634.65, { font: B, size: 9, maxW: 100 });
  put(c, dateSticker(d.endDate), x, 619.65, { font: B, size: 9, maxW: 100 });
  put(c, stickerNumber(d), 71.94, 601.43, { font: c.F.helv, size: 6, color: [0.2, 0.2, 0.2] });
  drawQr(c, d.verifyUrl, 197, 715.89, 52, 2);
  demoNote(c, 40, 584, 'left');
}

function drawCertificate(c) {
  const d = c.d, v = d.vehicle, B = c.F.timesB, R = c.F.times;
  const x = 311.52, right = 544;
  put(c, coverCert(d.coverType), right, 699.5, { font: R, size: 7.5, align: 'right' });
  put(c, certificateNumber(d), right, 680.25, { font: R, size: 9, align: 'right' });
  put(c, d.policyNumber, x, 665.93, { font: B, size: 11.2, maxW: 232 });
  put(c, v.plate, x, 643.43, { font: B, size: 11.2, maxW: 232 });
  put(c, String(d.client.name).toUpperCase(), x, 624.68, { font: B, size: 11.2, maxW: 232 });
  put(c, dateCert(d.startDate), x, 605.93, { font: B, size: 11.2, maxW: 232 });
  put(c, dateCert(d.endDate), x, 578.97, { font: B, size: 11.2, maxW: 232 });
  demoNote(c, 297.64, 16, 'center');
}

function drawBrownCard(c) {
  const d = c.d, v = d.vehicle, H = c.F.helv;
  const o = { font: H, size: 7.99 };
  // form fields (position = field origin + inner offset, as in the original)
  put(c, dateBrown(d.startDate), 245.21, 740.23, { ...o, maxW: 101 });                 // Valid from (top)
  put(c, dateBrown(d.endDate), 368.92, 740.17, { ...o, maxW: 81 });                    // To (top)
  put(c, d.policyNumber, 329.51, 718.83, { ...o, maxW: 121 });                         // 2 Original policy no
  put(c, String(d.client.name).toUpperCase(), 43.38, 705.21, { ...o, maxW: 185 });     // 1 Insured
  put(c, dateBrown(d.endDate), 400.58, 701.65, { ...o, maxW: 51 });                    // 3 Valid to
  put(c, dateBrown(d.startDate), 304.51, 700.26, { ...o, maxW: 76 });                  // 3 Valid from
  put(c, makeAndModel(v), 262.3, 665.28, { ...o, maxW: 189 });                         // 4 Make and type
  put(c, v.plate, 105.24, 663.48, { ...o, maxW: 123 });                                // 5 Registration
  put(c, v.chassisNo, 262.05, 639.27, { ...o, maxW: 189 });                            // 6 Chassis number
  put(c, usageBrown(v.use), 80.72, 539.89, { ...o, maxW: 148 });                       // 10 Usage
  // vertical card number, printed three times (front, back left, back right)
  const no = brownCardNumber(d);
  [[254.81, 592.81, 5], [64.86, 296.11, 6], [308.64, 287.58, 7]].forEach(([x, y, size]) => {
    const step = size * 0.79;
    for (let i = 0; i < no.length; i++) {
      put(c, no[i], x, y + i * step, { font: c.F.courier, size: size * 1.1, color: [0.2, 0.2, 0.2], rotate: c.L.degrees(90) });
    }
  });
  drawQr(c, d.verifyUrl, 30.41, 235.56, 51.8, 2);
  demoNote(c, 306, 30, 'center');
}

const DRAW = { sticker: drawSticker, certificate: drawCertificate, brown_card: drawBrownCard };
const TITLES = { sticker: 'Sticker', certificate: 'Certificate of Insurance', brown_card: 'Brown Card Certificate' };

/* ---------- public API ---------- */
function fileNameFor(type, d) {
  const plate = safe(d.vehicle.plate).replace(/\s+/g, '-');
  const date = String(d.startDate).replace(/-/g, '').slice(0, 8);
  return `${PREFIX[type]}_${plate}_${date}.pdf`;
}

async function buildPdf(type, d) {
  const L = await loadPdfLib();
  const pdf = await L.PDFDocument.load(b64ToBytes(TEMPLATES[type]), { updateMetadata: false });
  const F = {
    helv: await pdf.embedFont(L.StandardFonts.Helvetica),
    helvB: await pdf.embedFont(L.StandardFonts.HelveticaBold),
    times: await pdf.embedFont(L.StandardFonts.TimesRoman),
    timesB: await pdf.embedFont(L.StandardFonts.TimesRomanBold),
    courier: await pdf.embedFont(L.StandardFonts.Courier)
  };
  DRAW[type]({ L, page: pdf.getPage(0), F, d });
  pdf.setTitle(TITLES[type] + ' ' + safe(d.vehicle.plate));
  pdf.setCreator('Rescue Renewals');
  pdf.setProducer('Rescue Renewals');
  const bytes = await pdf.save();
  return new Blob([bytes], { type: 'application/pdf' });
}

export async function generateDocument(type, docContext) {
  if (!TEMPLATES[type]) throw new Error('Unknown document type: ' + type);
  const blob = await buildPdf(type, docContext);
  return { type, fileName: fileNameFor(type, docContext), blob, url: URL.createObjectURL(blob) };
}

export function generateAll(docContext) {
  return Promise.all(['sticker', 'certificate', 'brown_card'].map((t) => generateDocument(t, docContext)));
}

export function downloadDocument(doc) {
  const a = document.createElement('a');
  a.href = doc.url;
  a.download = doc.fileName;
  document.body.appendChild(a);
  a.click();
  a.remove();
}
